struct yetty_ycore_void_result yrdawn_encode_WGPUBlendComponent(const WGPUBlendComponent *src,
                                  struct yetty_ycore_buffer *out)
{
    { struct yetty_ycore_void_result wresult = yetty_ycore_buffer_write(out, &src->operation, sizeof(src->operation)); YETTY_RETURN_IF_ERR(yetty_ycore_void, wresult, "yrdawn_encode_WGPUBlendComponent"); }
    { struct yetty_ycore_void_result wresult = yetty_ycore_buffer_write(out, &src->srcFactor, sizeof(src->srcFactor)); YETTY_RETURN_IF_ERR(yetty_ycore_void, wresult, "yrdawn_encode_WGPUBlendComponent"); }
    { struct yetty_ycore_void_result wresult = yetty_ycore_buffer_write(out, &src->dstFactor, sizeof(src->dstFactor)); YETTY_RETURN_IF_ERR(yetty_ycore_void, wresult, "yrdawn_encode_WGPUBlendComponent"); }
    return YETTY_OK_VOID();
}


int yrdawn_decode_WGPUBlendComponent(void *ctx, const uint8_t **src, size_t *rem,
                                WGPUBlendComponent *out, struct yrdawn_arena *arena)
{
    (void)arena; (void)ctx;
    if (*rem < sizeof(out->operation)) return 0;
    memcpy(&out->operation, *src, sizeof(out->operation));
    *src += sizeof(out->operation); *rem -= sizeof(out->operation);
    if (*rem < sizeof(out->srcFactor)) return 0;
    memcpy(&out->srcFactor, *src, sizeof(out->srcFactor));
    *src += sizeof(out->srcFactor); *rem -= sizeof(out->srcFactor);
    if (*rem < sizeof(out->dstFactor)) return 0;
    memcpy(&out->dstFactor, *src, sizeof(out->dstFactor));
    *src += sizeof(out->dstFactor); *rem -= sizeof(out->dstFactor);
    return 1;
}

