    if (*rem < sizeof(out->vkYCbCrModel)) return 0;
    memcpy(&out->vkYCbCrModel, *src, sizeof(out->vkYCbCrModel));
    *src += sizeof(out->vkYCbCrModel); *rem -= sizeof(out->vkYCbCrModel);
