    *src += sizeof(out->vkYCbCrRange); *rem -= sizeof(out->vkYCbCrRange);
    if (*rem < sizeof(out->vkComponentSwizzleRed)) return 0;
    memcpy(&out->vkComponentSwizzleRed, *src, sizeof(out->vkComponentSwizzleRed));
    *src += sizeof(out->vkComponentSwizzleRed); *rem -= sizeof(out->vkComponentSwizzleRed);
    if (*rem < sizeof(out->vkComponentSwizzleGreen)) return 0;
    memcpy(&out->vkComponentSwizzleGreen, *src, sizeof(out->vkComponentSwizzleGreen));
    *src += sizeof(out->vkComponentSwizzleGreen); *rem -= sizeof(out->vkComponentSwizzleGreen);
    if (*rem < sizeof(out->vkComponentSwizzleBlue)) return 0;
    memcpy(&out->vkComponentSwizzleBlue, *src, sizeof(out->vkComponentSwizzleBlue));
    *src += sizeof(out->vkComponentSwizzleBlue); *rem -= sizeof(out->vkComponentSwizzleBlue);
    if (*rem < sizeof(out->vkComponentSwizzleAlpha)) return 0;
    memcpy(&out->vkComponentSwizzleAlpha, *src, sizeof(out->vkComponentSwizzleAlpha));
    *src += sizeof(out->vkComponentSwizzleAlpha); *rem -= sizeof(out->vkComponentSwizzleAlpha);
    if (*rem < sizeof(out->vkXChromaOffset)) return 0;
    memcpy(&out->vkXChromaOffset, *src, sizeof(out->vkXChromaOffset));
    *src += sizeof(out->vkXChromaOffset); *rem -= sizeof(out->vkXChromaOffset);
    if (*rem < sizeof(out->vkYChromaOffset)) return 0;
    memcpy(&out->vkYChromaOffset, *src, sizeof(out->vkYChromaOffset));
    *src += sizeof(out->vkYChromaOffset); *rem -= sizeof(out->vkYChromaOffset);
    if (*rem < sizeof(out->vkChromaFilter)) return 0;
    memcpy(&out->vkChromaFilter, *src, sizeof(out->vkChromaFilter));
    *src += sizeof(out->vkChromaFilter); *rem -= sizeof(out->vkChromaFilter);
